Table "Features" {
  "Feature_ID" INTEGER [pk, not null]
  "Feature_Details" TEXT
}

Table "Hotels" {
  "hotel_id" INTEGER [pk, not null]
  "star_rating_code" TEXT [not null]
  "pets_allowed_yn" TEXT
  "price_range" REAL
  "other_hotel_details" TEXT
}

Table "Locations" {
  "Location_ID" INTEGER [pk, not null]
  "Location_Name" TEXT
  "Address" TEXT
  "Other_Details" TEXT
}

Table "Museums" {
  "Museum_ID" INTEGER [pk, not null]
  "Museum_Details" TEXT
}

Table "Photos" {
  "Photo_ID" INTEGER [pk, not null]
  "Tourist_Attraction_ID" INTEGER [not null]
  "Name" TEXT
  "Description" TEXT
  "Filename" TEXT
  "Other_Details" TEXT
}

Table "Ref_Attraction_Types" {
  "Attraction_Type_Code" TEXT [pk, not null]
  "Attraction_Type_Description" TEXT
}

Table "Ref_Hotel_Star_Ratings" {
  "star_rating_code" TEXT [pk, not null]
  "star_rating_description" TEXT
}

Table "Royal_Family" {
  "Royal_Family_ID" INTEGER [pk, not null]
