  "Other_Details" TEXT
}

Table "Street_Markets" {
  "Market_ID" INTEGER [pk, not null]
  "Market_Details" TEXT
}

Table "Theme_Parks" {
  "Theme_Park_ID" INTEGER [pk, not null]
  "Theme_Park_Details" TEXT
}

Table "Tourist_Attraction_Features" {
  "Tourist_Attraction_ID" INTEGER [pk, not null]
  "Feature_ID" INTEGER [pk, not null]
}

Table "Tourist_Attractions" {
  "Tourist_Attraction_ID" INTEGER [pk, not null]
  "Attraction_Type_Code" TEXT [not null]
  "Location_ID" INTEGER [not null]
  "How_to_Get_There" TEXT
  "Name" TEXT
  "Description" TEXT
  "Opening_Hours" TEXT
  "Other_Details" TEXT
}

Table "Visitors" {
  "Tourist_ID" INTEGER [pk, not null]
  "Tourist_Details" TEXT
}

Table "Visits" {
  "Visit_ID" INTEGER [pk, not null]
  "Tourist_Attraction_ID" INTEGER [not null]
  "Tourist_ID" INTEGER [not null]
  "Visit_Date" TIMESTAMP [not null]
  "Visit_Details" TEXT [not null]
}



